            aPrevious = aIngress;
            //
            aIngress = (RotL64(aWaterLaneA[((aIndex + 11482U)) & S_BLOCK1], 29U) ^ RotL64(aWindLaneC[((aIndex + 12394U)) & S_BLOCK1], 48U));
            aIngress ^= (RotL64(aPoisonLaneB[((aIndex + 11160U)) & S_BLOCK1], 5U) ^ RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 8504U)) & S_BLOCK1], 21U));
