            aOrbiterF = (((aWandererK + RotL64(aPrevious, 41U)) + RotL64(aCarry, 35U)) + 0x23B543CFE8406247ULL) + aPhaseDOrbiterAssignSaltD[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterG = ((aWandererC + RotL64(aScatter, 11U)) + RotL64(aCarry, 51U)) + 0x89F395F9DD378E53ULL;
            aOrbiterD = ((aWandererH + RotL64(aIngress, 5U)) + RotL64(aCarry, 21U)) + 0x0D569FB31E646659ULL;
