            aOrbiterJ = RotL64((aOrbiterJ * 0xF90A12C1549EAAE1ULL), 19U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0x62BA71C1860AF8EFULL) + aPhaseDOrbiterUpdateSaltE[(((31U - aIndex) + 28U)) & S_SALT1];
