            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0x1B5419E1C8A321E4ULL) + aPhaseDOrbiterUpdateSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x0E4FA3DCD1938561ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xAECC2517A4A7DADFULL), 3U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0xCCD9E910F578A893ULL) + aPhaseDOrbiterUpdateSaltA[(((31U - aIndex) + 26U)) & S_SALT1];
