            aOrbiterA = (aOrbiterA + aOrbiterG) + 0xE8B51F2DDF1A59C9ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0x6D6DEB8C5E6ED1C2ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xD76615C5B9453B61ULL), 11U);
            //
            aIngress = RotL64(aOrbiterA, 19U) ^ aOrbiterK;
