            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x636163D08F4B0537ULL) + aPhaseBOrbiterUpdateSaltA[((aIndex + 16U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0xB81F50C35B1E64ACULL;
