            aOrbiterK = (aWandererF + RotL64(aPrevious, 41U)) + 0xDD9C4824DF91E4A5ULL;
            aOrbiterG = ((aWandererJ + RotL64(aScatter, 21U)) + 0xAFD1A90659122CE0ULL) + aPhaseCOrbiterAssignSaltE[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aCross, 13U)) + 0x0E1C711A31502F66ULL;
            aOrbiterC = ((aWandererK + RotL64(aIngress, 35U)) + RotL64(aCarry, 53U)) + 0x436FE174F9550E68ULL;
            aOrbiterD = (((aWandererI + RotL64(aScatter, 6U)) + RotL64(aCarry, 23U)) + 0xE3B3864EEAE82C44ULL) + aPhaseCOrbiterAssignSaltA[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterI = (aWandererE + RotL64(aPrevious, 47U)) + 0x89E9219780E6834DULL;
