            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xD83A6B8C15AEE087ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0x128C2BAC4E463611ULL) ^ aPhaseCOrbiterUpdateSaltF[((aIndex + 28U)) & S_SALT1];
