            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x4F73087830212B6FULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterI) ^ 0x3D0B88A15D7EE3BAULL) ^ aPhaseCOrbiterUpdateSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
