            aOrbiterA = ((aOrbiterA + aOrbiterK) + 0x4AADDBC6BBC54460ULL) + aPhaseCOrbiterUpdateSaltC[((aIndex + 20U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0xDDF9BB497E3EE44AULL) ^ aPhaseCOrbiterUpdateSaltE[(((31U - aIndex) + 4U)) & S_SALT1];
