            //
            aWandererE = aWandererE ^ (((RotL64(aScatter, 37U) + RotL64(aOrbiterF, 20U)) + aOrbiterG) + aPhaseCWandererUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1]);
